func:
// Vào: link in 'state' (pomodoro/state) + inject 'clock' mỗi 1 giây
// Ra: 5 ô chữ group Trạng thái hộp (Kết nối, Trạng thái, Môn, Chu kỳ, Thời gian còn lại)
const LABEL = { idle: 'Chờ bắt đầu', study: 'Đang học', break: 'Nghỉ giải lao', paused: 'Tạm dừng', done: 'Hoàn thành' };
const now = Date.now();
if (msg.topic !== 'clock') {
    context.set('last', msg.payload || {});
    context.set('seen', now);
}
const s = context.get('last');
if (!s) return [{ payload: 'Chưa có tin' }, null, null, null, null];
const ago = Math.floor((now - context.get('seen')) / 1000);
// Hộp gửi nhịp tim 'tick' mỗi 30 s -> quá 70 s không có tin là Offline
const online = ago < 70;
const running = s.state === 'study' || s.state === 'break';
const remain = running ? Math.max(0, (s.remain || 0) - ago) : (s.remain || 0);
const mm = String(Math.floor(remain / 60)).padStart(2, '0');
const ss = String(remain % 60).padStart(2, '0');
return [
    { payload: online ? 'Online' : `Offline (${Math.floor(ago / 60)} phút trước)` },
    { payload: LABEL[s.state] || s.state },
    { payload: s.subject || '—' },
    { payload: s.cycle ? `${s.cycle} / ${s.total}` : `— / ${s.total}` },
    { payload: `${mm}:${ss}` }
];

// Vào: link in 'lux' ({lux: ADC 0..4095} mỗi 2 s), slider ngưỡng (topic 'threshold'), inject 'init'
// Ra: 1 = gauge %, 2 = ô Tình trạng, 3 = đặt lại slider lúc khởi động
const LUX_INVERT = true;   // module LDR: càng sáng ADC càng NHỎ -> đảo. Che tay mà % TĂNG thì đổi thành false
// ponytail: ánh xạ tuyến tính, cần hiệu chuẩn với đèn bàn thật
let thr = flow.get('luxThreshold') ?? 30;   // Task 3.K2 chuyển ngưỡng sang bảng settings
if (msg.topic === 'init') return [null, null, { payload: thr }];
if (msg.topic === 'threshold') {
    thr = Number(msg.payload);
    flow.set('luxThreshold', thr);
} else {
    const raw = msg.payload && msg.payload.lux;
    if (typeof raw !== 'number') return null;
    context.set('pct', Math.round(LUX_INVERT ? 100 - raw / 40.95 : raw / 40.95));
}
const pct = context.get('pct');
if (pct === undefined) return null;
const segments = [{ from: 0, color: '#ea5353' }, { from: thr, color: '#e6e600' }, { from: Math.min(100, thr + 30), color: '#5cd65c' }];
return [
    { payload: pct, dev: msg.payload && msg.payload.dev, ui_update: { segments } },
    { payload: pct < thr ? `Thiếu sáng (${pct}% < ngưỡng ${thr}%)` : 'Đủ sáng' },
    null
];

// ID8 â€“ pomodoro/state -> báº£ng events (bá» nhá»‹p tim 'tick' vÃ  thiáº¿t bá»‹ giáº£ láº­p)
const p = msg.payload || {};
if (p.dev !== 'pomo-01' || p.event === 'tick' || !p.ts) return null;
return {
    table: 'events',
    payload: { dev: p.dev, ts: new Date(p.ts * 1000).toISOString(), type: p.event, detail: p }
};

// ID8 â€“ gom % Ä‘á»™ sÃ¡ng (tá»« hÃ m ID5, má»—i 2 s) thÃ nh trung bÃ¬nh 60 s -> báº£ng lux_readings
if (msg.dev !== 'pomo-01' || typeof msg.payload !== 'number') return null;
const now = Date.now();
const a = context.get('acc') || { sum: 0, n: 0, start: now };
a.sum += msg.payload; a.n++;
if (now - a.start < 60000) { context.set('acc', a); return null; }
context.set('acc', { sum: 0, n: 0, start: now });
return {
    table: 'lux_readings',
    payload: { dev: msg.dev, ts: new Date(now).toISOString(), lux_avg: Math.round(a.sum / a.n * 10) / 10 }
};

// ID8 â€“ pomodoro/session -> upsert báº£ng sessions (gá»­i láº¡i cÃ¹ng start_ts khÃ´ng táº¡o dÃ²ng trÃ¹ng)
const p = msg.payload || {};
if (p.dev !== 'pomo-01' || !p.start_ts) return null;
const iso = (u) => u ? new Date(u * 1000).toISOString() : null;
return {
    table: 'sessions',
    query: '?on_conflict=dev,start_ts',
    prefer: 'resolution=merge-duplicates',
    ack_ts: p.start_ts,
    payload: {
        dev: p.dev, start_ts: iso(p.start_ts), end_ts: iso(p.end_ts), subject: p.subject,
        cycle: p.cycle, total: p.total, planned_min: p.planned_min, focus_min: p.focus_min,
        pauses: p.pauses || 0, pause_sec: p.pause_sec || 0, completed: !!p.completed
    }
};

// ID8 â€“ dá»±ng request REST tá»›i Supabase (dÃ¹ng chung cho má»i luá»“ng ghi)
// VÃ o: msg.table, msg.payload (1 dÃ²ng), tÃ¹y chá»n msg.query ("?on_conflict=..."), msg.prefer
msg.url = env.get('SUPABASE_URL') + '/rest/v1/' + msg.table + (msg.query || '');
msg.method = msg.method || 'POST';
const key = env.get('SUPABASE_KEY');
msg.headers = {
    apikey: key,
    Authorization: 'Bearer ' + key,
    'Content-Type': 'application/json',
    Prefer: (msg.prefer ? msg.prefer + ',' : '') + 'return=minimal'
};
return msg;

// ID8 â€“ káº¿t quáº£ ghi Supabase. Ra 1: ack phiÃªn (2xx + cÃ³ ack_ts) -> to-ack. Ra 2: lá»—i -> debug
const ok = msg.statusCode >= 200 && msg.statusCode < 300;
if (!ok) {
    node.status({ fill: 'red', shape: 'dot', text: `${msg.table}: ${msg.statusCode}` });
    return [null, { payload: { table: msg.table, status: msg.statusCode, body: msg.payload } }];
}
node.status({ fill: 'green', shape: 'dot', text: `${msg.table} OK ${new Date().toLocaleTimeString('vi-VN')}` });
if (msg.ack_ts) return [{ payload: { start_ts: msg.ack_ts } }, null];
return null;

// ID5 – lúc Node-RED khởi động: đọc ngưỡng thiếu sáng từ bảng settings (key = lux_threshold)
const key = env.get('SUPABASE_KEY');
msg.url = env.get('SUPABASE_URL') + '/rest/v1/settings?key=eq.lux_threshold&select=value';
msg.method = 'GET';
msg.headers = { apikey: key, Authorization: 'Bearer ' + key };
return msg;

// ID5 – nạp ngưỡng vào flow context rồi báo hàm ID5 đặt lại slider ('init')
const v = Array.isArray(msg.payload) && msg.payload[0] ? Number(msg.payload[0].value) : NaN;
if (msg.statusCode === 200 && !isNaN(v)) {
    flow.set('luxThreshold', v);
    node.status({ fill: 'green', shape: 'dot', text: `ngưỡng ${v}% (Supabase)` });
} else {
    node.status({ fill: 'red', shape: 'dot', text: `lỗi đọc settings (${msg.statusCode}), dùng ${flow.get('luxThreshold') ?? 30}%` });
}
return { topic: 'init' };

// ID5 – kéo slider xong -> PATCH settings.lux_threshold
return {
    table: 'settings',
    query: '?key=eq.lux_threshold',
    method: 'PATCH',
    payload: { value: Number(msg.payload), updated_at: new Date().toISOString() }
};

// ID5 – cảnh báo thiếu sáng: đang học + % < ngưỡng LIÊN TỤC 30 s -> lời nhắc OLED + còi 2 tiếng + events low_light
// Tối đa 1 lần / 5 phút. Vào: % độ sáng (đầu ra 1 hàm ID5, có msg.dev) và link in 'state'.
// Ra: 1 = to-cmd, 2 = ghi events, 3 = ô "Cảnh báo thiếu sáng" (group Trạng thái hộp)
const HOLD_MS = 30000, GAP_MS = 5 * 60000;
const now = Date.now();
if (msg.topic === 'pomodoro/state' || (msg.payload && msg.payload.state)) {
    if (msg.payload.dev === 'pomo-01') { context.set('state', msg.payload.state); flow.set('boxState', msg.payload.state); }   // boxState: 4.K3 dùng
    return null;
}
if (msg.dev !== 'pomo-01' || typeof msg.payload !== 'number') return null;
const pct = msg.payload, thr = flow.get('luxThreshold') ?? 30;
const last = context.get('lastAlert') || 0;
const lastTxt = last && now - last < GAP_MS
    ? `Đã cảnh báo lúc ${new Date(last).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })}` : null;
if (context.get('state') !== 'study' || pct >= thr) {
    context.set('since', null);
    node.status({});
    return [null, null, { payload: lastTxt || 'Không có' }];
}
const since = context.get('since') || now;
context.set('since', since);
const secs = Math.round((now - since) / 1000);
node.status({ fill: 'yellow', shape: 'ring', text: `thiếu sáng ${secs} s` });
if (now - since < HOLD_MS || now - last < GAP_MS) return [null, null, { payload: lastTxt || `Thiếu sáng ${secs} s (${pct}% < ${thr}%)` }];
context.set('lastAlert', now);
node.status({ fill: 'red', shape: 'dot', text: `đã cảnh báo ${new Date(now).toLocaleTimeString('vi-VN')}` });
return [
    [{ payload: { type: 'msg', text: 'Phong thieu sang, hay bat den!', sec: 10 } },
     { payload: { type: 'beep', times: 2 } }],
    { table: 'events', payload: { dev: 'pomo-01', ts: new Date(now).toISOString(), type: 'low_light', detail: { pct, threshold: thr } } },
    { payload: `Đã cảnh báo lúc ${new Date(now).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })}` }
];

// ID6 – học xong cả phiên (event "done" của hộp thật) -> tin Telegram cho phụ huynh
// Gọi thẳng Bot API bằng http request + env TELEGRAM_TOKEN: không cần credential, máy nào có env là chạy.
const p = msg.payload || {};
if (p.dev !== 'pomo-01' || p.event !== 'done') return null;
if (flow.get('tgEnabled') === false) { node.status({ fill: 'grey', shape: 'ring', text: 'đang tắt, không gửi' }); return null; }
const hhmm = new Date((p.ts || Date.now() / 1000) * 1000)
    .toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Ho_Chi_Minh' });
const subject = p.subject && p.subject !== 'Chua chon mon' ? p.subject : '(chưa chọn môn)';
return {
    kind: 'send',
    url: `https://api.telegram.org/bot${env.get('TELEGRAM_TOKEN')}/sendMessage`,
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    payload: { chat_id: env.get('TELEGRAM_CHAT_ID'), text: `Đã học xong ${p.total} chu kỳ môn ${subject} lúc ${hhmm}` }
};

context.set('last', { kind: msg.kind, status: msg.statusCode, ok: !!(msg.payload && msg.payload.ok), at: new Date().toISOString() });
// ID6 – kết quả gọi Telegram. Ra 1: ô Trạng thái bot. Ra 2: lỗi gửi -> debug (KHÔNG kèm msg.url vì chứa token)
const ok = msg.statusCode === 200 && msg.payload && msg.payload.ok;
if (msg.kind === 'ping') {
    const name = ok ? '@' + msg.payload.result.username : '';
    return [{ payload: ok ? `Đã kết nối (${name})` : `Chưa kết nối (${msg.statusCode || 'mất mạng'})` }, null];
}
if (ok) {
    node.status({ fill: 'green', shape: 'dot', text: `đã gửi ${new Date().toLocaleTimeString('vi-VN')}` });
    return null;
}
node.status({ fill: 'red', shape: 'dot', text: `gửi lỗi ${msg.statusCode}` });
return [null, { payload: { status: msg.statusCode, telegram: msg.payload && msg.payload.description } }];

// ID6 – lúc khởi động: đọc settings.telegram_enabled để đặt công tắc
const key = env.get('SUPABASE_KEY');
msg.url = env.get('SUPABASE_URL') + '/rest/v1/settings?key=eq.telegram_enabled&select=value';
msg.method = 'GET';
msg.headers = { apikey: key, Authorization: 'Bearer ' + key };
return msg;

// ID6 – nạp trạng thái công tắc (mặc định bật nếu đọc lỗi)
const row = Array.isArray(msg.payload) && msg.payload[0];
const on = row ? row.value !== false : true;
flow.set('tgEnabled', on);
node.status({ fill: row ? 'green' : 'yellow', shape: 'dot', text: (on ? 'bật' : 'tắt') + (row ? ' (Supabase)' : ' (mặc định)') });
return { payload: on };

// ID6 – gạt công tắc -> nhớ ngay + PATCH settings.telegram_enabled
const on = !!msg.payload;
flow.set('tgEnabled', on);
return { table: 'settings', query: '?key=eq.telegram_enabled', method: 'PATCH',
         payload: { value: on, updated_at: new Date().toISOString() } };

// 4.K3 – mở trang Tổng quan thì tải lại nhật ký
if (msg.topic !== '$pageview') return null;
const path = (msg.payload && msg.payload.page && msg.payload.page.path) || '';
return path === '/tong-quan' ? { payload: 'refresh' } : null;

// 4.K3 – GET song song sessions + low_light của HÔM NAY (giờ VN, UTC+7) -> 2 request cùng reqId
const VN = 7 * 3600e3;
const vn = new Date(Date.now() + VN);
const from = new Date(Date.UTC(vn.getUTCFullYear(), vn.getUTCMonth(), vn.getUTCDate()) - VN).toISOString();
const key = env.get('SUPABASE_KEY'), base = env.get('SUPABASE_URL') + '/rest/v1/';
const headers = { apikey: key, Authorization: 'Bearer ' + key };
const reqId = Date.now();
return [[
    { reqId, part: 'sessions', method: 'GET', headers,
      url: base + `sessions?dev=eq.pomo-01&start_ts=gte.${from}&select=start_ts,end_ts,subject,cycle,total,planned_min,focus_min,pauses,pause_sec,completed&order=start_ts` },
    { reqId, part: 'low', method: 'GET', headers: { ...headers },   // 2 msg không dùng chung 1 object
      url: base + `events?dev=eq.pomo-01&type=eq.low_light&ts=gte.${from}&select=ts,detail&order=ts` }
]];

// 4.K3 – ghép 2 kết quả cùng reqId thành bảng Nhật ký học hôm nay, sắp theo giờ
// 1 dòng = 1 chu kỳ; thêm 1 dòng "Dừng giữa phiên" khi phiên kết thúc trước khi đủ số chu kỳ đã đặt.
if (msg.statusCode !== 200) {
    node.status({ fill: 'red', shape: 'dot', text: `${msg.part}: ${msg.statusCode}` });
    return null;
}
const parts = context.get('parts') || {};
if (parts.reqId !== msg.reqId) { parts.reqId = msg.reqId; parts.sessions = null; parts.low = null; }
parts[msg.part] = msg.payload || [];
context.set('parts', parts);
if (!parts.sessions || !parts.low) return null;

const hhmm = (iso) => new Date(iso).toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Ho_Chi_Minh' });
const subj = (s) => s && s !== 'Chua chon mon' ? s : '(chưa chọn môn)';
const ss = parts.sessions;
const rows = ss.map(s => ({
    t: s.start_ts,
    'Giờ': hhmm(s.start_ts),
    'Môn': subj(s.subject),
    'Chu kỳ': `${s.cycle}/${s.total}`,
    'Thời lượng': `${s.focus_min}/${s.planned_min} phút`,
    'Tạm dừng': s.pauses ? `${s.pauses} lần (${Math.round((s.pause_sec || 0) / 60)} phút)` : 'Không',
    'Kết quả': s.completed ? 'Hoàn thành' : 'Bỏ dở'
}));

// Gom phiên: chu kỳ sau = chu kỳ trước + 1, cùng tổng, cách nhau < 2 giờ
const phien = [];
for (const s of ss) {
    const p = phien[phien.length - 1], last = p && p[p.length - 1];
    const tiep = last && s.cycle === last.cycle + 1 && s.total === last.total &&
                 new Date(s.start_ts) - new Date(last.start_ts) < 2 * 3600e3;
    if (tiep) p.push(s); else phien.push([s]);
}
const boxBusy = ['study', 'break', 'paused'].includes(flow.get('boxState'));
phien.forEach((p, i) => {
    const last = p[p.length - 1];
    if (last.cycle >= last.total) return;                       // đủ chu kỳ -> phiên trọn
    if (i === phien.length - 1 && boxBusy) return;              // phiên cuối đang chạy -> chưa kết luận
    const end = last.end_ts || last.start_ts;
    rows.push({
        t: new Date(new Date(end).getTime() + 1).toISOString(),  // ngay sau chu kỳ cuối
        'Giờ': hhmm(end), 'Môn': subj(last.subject), 'Chu kỳ': `${last.cycle}/${last.total}`,
        'Thời lượng': `${p.reduce((a, s) => a + (s.focus_min || 0), 0)} phút`, 'Tạm dừng': '—',
        'Kết quả': `Dừng giữa phiên (${last.cycle}/${last.total} chu kỳ)`
    });
});

for (const e of parts.low) rows.push({
    t: e.ts, 'Giờ': hhmm(e.ts), 'Môn': '—', 'Chu kỳ': '—', 'Thời lượng': '—', 'Tạm dừng': '—',
    'Kết quả': `Cảnh báo thiếu sáng (${e.detail && e.detail.pct}%)`
});
rows.sort((a, b) => new Date(a.t) - new Date(b.t));
context.set('summary', phien.length + ' phiên');
node.status({ fill: 'green', shape: 'dot', text: `${ss.length} chu kỳ, ${phien.length} phiên, ${parts.low.length} cảnh báo – ${new Date().toLocaleTimeString('vi-VN')}` });
return { payload: rows.map(({ t, ...r }) => r) };
